import { Label, Meter as AriaMeter } from "react-aria-components";
import type { MeterProps as AriaMeterProps } from "react-aria-components";
import type { Ref } from "react";
import "./Meter.css";

/**
 * Valence — how the reading should be *judged*, not what it is.
 *
 * This is the axis that separates a meter from a progress bar. A meter's value carries a
 * quality (95% disk used is bad, 95% battery is good); a task's progress does not, which is
 * why native `<meter>` has `low`/`high`/`optimum` and `<progress>` has nothing of the kind.
 * `ProgressBar` deliberately has no such axis — that asymmetry IS the distinction.
 *
 * Left to the caller rather than derived from thresholds: React Aria gives Meter no
 * low/high/optimum (`MeterProps` is a bare alias of the shared base), and the native
 * three-region × three-optimum-placement algorithm is subtle enough that hand-rolling it would
 * be the library's only piece of derived visual logic. Peer precedent agrees — Spectrum's Meter
 * takes an explicit variant too.
 */
type MeterVariant = "standard" | "success" | "warning" | "error";

/** Meter props shared by every naming shape (the React Aria value/range axis). */
export type MeterBaseProps = Omit<AriaMeterProps, "className" | "children">;

/**
 * Meter props.
 *
 * React Aria renders `role="meter"`, which **requires an accessible name** (WCAG 4.1.2 —
 * axe: `accessibleNameRequired`). So the name is mandatory at the type level: pass a visible
 * `label`, or — when the meter is named by neighbouring content — `aria-label` /
 * `aria-labelledby`. Omitting all three does not compile.
 * (The contract's only sanctioned discriminated-union shape — component-contract.md §2,
 * same pattern as Button's `isIconOnly`.)
 */
export type MeterProps = MeterBaseProps & {
  /**
   * How the reading reads: neutral (`standard`) or a judgement. See {@link MeterVariant}.
   *
   * @default "standard"
   */
  variant?: MeterVariant;
  /**
   * Show the formatted value beside the label.
   *
   * React Aria already computes it — `valueText` (`valueLabel` when given, else the value run
   * through `formatOptions`, which defaults to `{ style: "percent" }`) — and exposes it as a
   * render prop **and** as `aria-valuetext`. Without this the value reaches assistive tech only,
   * so a sighted reader sees an unlabelled bar. Off by default: a bar used as pure decoration
   * beside its own copy (an upload row, a step indicator) should not repeat the number.
   */
  showValue?: boolean;
} & (
    | { label: string }
    | { label?: undefined; "aria-label": string }
    | { label?: undefined; "aria-labelledby": string }
  ) & {
    /** Additional class. sd-meter is always retained. */
    className?: string;
    /** Passed to the root meter DOM element. */
    ref?: Ref<HTMLDivElement>;
  };

/**
 * Meter — a **standing reading within a known range** (disk used, battery, rating distribution).
 *
 * **Meter or ProgressBar?** A meter persists, moves in both directions, and its value carries a
 * good/bad quality. A `ProgressBar` tracks **one operation over time** — it appears, advances
 * toward completion, and goes away; 95% there just means "nearly done", with no valence to it.
 * The test: *does it end and disappear?* → `ProgressBar`. *Is it a standing value that can go up
 * or down?* → `Meter`. Two consequences follow, and they are the only differences in meaning between the
 * two: only `ProgressBar` can be **indeterminate** (a measurement with no value is not a
 * measurement), and only `Meter` has a **`variant`** (the valence).
 *
 * @usageInvariant meter-progressbar-axes
 */
export function Meter({
  variant = "standard",
  showValue = false,
  label,
  minValue = 0,
  maxValue = 100,
  className,
  ref,
  ...props
}: MeterProps) {
  return (
    <AriaMeter
      {...props}
      ref={ref}
      data-variant={variant}
      minValue={minValue}
      maxValue={maxValue}
      className={className ? `sd-meter ${className}` : "sd-meter"}
    >
      {({ percentage, valueText }) => {
        // The label/value row only exists when it has something in it — an always-rendered
        // header would add its own gap above a bare track.
        const shownValue = showValue ? valueText : undefined;
        return (
          <>
            {(label || shownValue) && (
              <div className="sd-meter__header">
                {label && <Label className="sd-meter__label sd-type-label-medium">{label}</Label>}
                {/* Decorative on purpose: this span is a VISUAL MIRROR of `aria-valuetext`
                    (literally the same string — React Aria feeds the render prop from that very
                    attribute), so assistive tech already has the value from the meter itself.
                    Leaving it exposed risks announcing the number twice, the same double-read
                    `Spinner`'s `isDecorative` and `Skeleton`'s always-hidden contract exist to
                    prevent. Verified against the CDP accessibility tree. */}
                {shownValue && (
                  <span aria-hidden="true" className="sd-meter__value sd-type-body-medium">
                    {shownValue}
                  </span>
                )}
              </div>
            )}
            <div className="sd-meter__track">
              <div className="sd-meter__fill" style={{ width: `${percentage ?? 0}%` }} />
            </div>
          </>
        );
      }}
    </AriaMeter>
  );
}

.sd-meter {
  /* Resting value of the state-on-root → style-on-child hop, declared on the base class like
     Checkbox/Switch do (component-contract §6 rule 5) — so the fill still paints if the root
     ever renders without `data-variant` (hand-written copy-paste markup). The four explicit
     `[data-variant]` rules below then set it per value, Button/Badge-style. */
  --sd-meter-fill-background-current: var(--sd-meter-fill-background-standard);

  display: flex;
  flex-direction: column;
  gap: var(--sd-meter-gap);
  width: var(--sd-meter-width);
}

/* Label left, value right, on one baseline — the label may wrap, the value never shrinks. */
.sd-meter__header {
  display: flex;
  align-items: baseline;
  gap: var(--sd-meter-header-gap);
}

.sd-meter__label {
  color: var(--sd-meter-label-foreground);
}

/* `margin-inline-start: auto` rather than `justify-content: space-between` on the row: the two
   agree while both parts render, but space-between falls back to flex-start when the value is
   the ONLY item (no visible label), which moves the value out of its slot. These are positional
   slots — stack several meters and every value must line up whether or not each has a label. */
.sd-meter__value {
  /* A value that changes in place (a count, a percentage) keeps its width, so it does not jitter as
     its digits change. */
  font-variant-numeric: tabular-nums;
  flex: 0 0 auto;
  margin-inline-start: auto;
  color: var(--sd-meter-value-foreground);
}

.sd-meter__track {
  overflow: hidden;
  height: var(--sd-meter-track-height);
  background: var(--sd-meter-track-background);
  border-radius: var(--sd-meter-track-radius);
  corner-shape: round;
}

/* Valence sits on the root (it is the whole reading's quality) but paints the fill, so it takes
   the sanctioned state-on-root → style-on-child hop via a local `-current` intermediate
   (component-contract §6 rule 5) — a descendant combinator is not allowed. Every value gets its
   own selector, including the default, matching Button/Badge. */
.sd-meter[data-variant="standard"] {
  --sd-meter-fill-background-current: var(--sd-meter-fill-background-standard);
}
.sd-meter[data-variant="success"] {
  --sd-meter-fill-background-current: var(--sd-meter-fill-background-success);
}
.sd-meter[data-variant="warning"] {
  --sd-meter-fill-background-current: var(--sd-meter-fill-background-warning);
}
.sd-meter[data-variant="error"] {
  --sd-meter-fill-background-current: var(--sd-meter-fill-background-error);
}

.sd-meter__fill {
  width: 0;
  height: 100%;
  background: var(--sd-meter-fill-background-current);
  border-radius: var(--sd-meter-fill-radius);
  corner-shape: round;
  transition: width var(--sd-duration-slow) var(--sd-easing-standard);
}

@media (prefers-reduced-motion: reduce) {
  .sd-meter__fill {
    transition: none;
  }
}
